return $input.all().map(({json:n}) => ({
  titulo: limpar(n.title), link: limpar(n.link).replace(/^\[([^\]]+)\]\([^)]*\)$/, '$1'),
  trecho: limpar(n.contentSnippet || n['content:encodedSnippet'] || n.description || n.content || n['content:encoded']).slice(0, 5000),
