const formulario = $input.first().json;
const instancia = 'SEU_CLIENTE';
const baseUrl = 'http://evolution-api:8080';
const escolha = String(formulario.opcao ?? formulario['O que você quer consultar?'] ?? '').trim();
const filtro = String(formulario.filtro ?? formulario['Filtrar por nome (opcional)'] ?? '').trim().slice(0, 120);
const opcoes = {
  'Todos os grupos e comunidades': 'todos',
  'Grupos comuns': 'grupos',
  'Comunidades': 'comunidades',
  'Grupos de avisos': 'avisos',
  'Instância e conexão': 'instancia',
  'Canais de voz (disponibilidade)': 'voz',
};
const tipo = opcoes[escolha];
if (!tipo) throw new Error('Escolha uma das opções do formulário de consulta.');
const consultarAPI = tipo !== 'voz';
const url = tipo === 'instancia'
  ? `${baseUrl}/instance/connectionState/${instancia}`
  : `${baseUrl}/group/fetchAllGroups/${instancia}?getParticipants=false`;
return [{json: {tipo, filtro, instancia, consultarAPI, url}}];

const consulta = $('IDs · Preparar consulta').first().json;
const normalizar = texto => String(texto || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
if (consulta.tipo === 'voz') return [{json: {
  nome: 'Canais de voz', id: '', tipo: 'Indisponível nesta consulta',
  observacao: 'A Evolution API 2.3.7 não oferece uma rota para listar IDs de canais de voz. Comunidades e grupos de avisos do WhatsApp são categorias diferentes. Nenhuma chamada é iniciada por este bloco.',
}}];
const entradas = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
if (consulta.tipo === 'instancia') {
  const info = entradas[0]?.instance;
  if (!info || typeof info.state !== 'string') throw new Error('A Evolution não retornou o estado esperado da instância.');
  return [{json:{nome:info.instanceName || consulta.instancia, id:info.instanceName || consulta.instancia, tipo:'Instância', estado:info.state, observacao:'Este é o nome da conexão. Para enviar, use um telefone ou ID de grupo como destinatário.'}}];
}
const grupos = entradas.flatMap(item=>Array.isArray(item.groups) ? item.groups : [item]);
const vistos = new Set();
const filas = grupos.filter(g=>{
  if (!g || typeof g.id !== 'string' || !g.id.endsWith('@g.us') || vistos.has(g.id)) return false;
  vistos.add(g.id);
  if (consulta.tipo === 'grupos' && (g.isCommunity || g.isCommunityAnnounce)) return false;
  if (consulta.tipo === 'comunidades' && !g.isCommunity) return false;
  if (consulta.tipo === 'avisos' && !g.isCommunityAnnounce && !g.announce) return false;
  return !consulta.filtro || normalizar(g.subject).includes(normalizar(consulta.filtro));
}).map(g=>({json:{
  nome:String(g.subject || 'Sem nome').trim(), id:g.id,
  tipo:g.isCommunity ? 'Comunidade (estrutura principal)' : g.isCommunityAnnounce ? 'Grupo de avisos da comunidade' : g.announce ? 'Grupo somente administradores' : 'Grupo comum',
  participantes:g.size ?? null,
  comunidade:g.linkedParent || '',
  observacao:g.isCommunity ? 'Para publicar avisos, procure o grupo de avisos vinculado a esta comunidade.' : 'Copie o ID para o destinatário quando desejar. Esta consulta não altera o destino do workflow.',
}})).sort((a,b)=>a.json.nome.localeCompare(b.json.nome,'pt-BR'));
return filas.length ? filas : [{json:{nome:'Nenhum resultado',id:'',tipo:consulta.tipo,observacao:'Tente outra categoria ou remova o filtro por nome.'}}];

const origem = $('Montar Prompt').first(0, 0).json;
const anterior = $input.first().json;
const tentativa = Number(anterior.tentativaGemini || 0) + 1;
return [{json: {...origem, tentativaGemini: tentativa}}];

const resposta = $input.first().json;
const tentativa = $('Gemini · Preparar tentativa').first(0, -1).json.tentativaGemini;
const LIMITE_TENTATIVAS = 6; // 1ª chamada + 5 reintentos imediatos; depois, erro rápido e claro.
let body = resposta.body;
let status = Number(resposta.statusCode || 0);
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = null; }
}
if (!status && resposta.error && typeof resposta.error === 'object') {
  status = Number(resposta.error.httpCode || resposta.error.statusCode || 0);
}
const erro = resposta.error;
const textoErro = typeof erro === 'string' ? erro : [erro?.message, erro?.description, erro?.code, erro?.cause?.code].filter(Boolean).join(' ');
const transitorioHttp = status === 408 || status === 429 || (status >= 500 && status <= 599);
const transitorioRede = !status && /timeout|timed.?out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|ECONNREFUSED|EAI_AGAIN|ENOTFOUND|socket|connection.*(?:closed|reset|aborted)|offline|network|temporar/i.test(textoErro);
if (status >= 200 && status < 300 && body && !body.error) {
  // O resultado segue apenas uma vez para a validação editorial e os envios.
  return [{json: {...body, geminiConcluido: true, tentativaGemini: tentativa}}];
}
if (!transitorioHttp && !transitorioRede) {
  const codigo = status || 'configuração';
  throw new Error(`Gemini: erro ${codigo} não temporário. Confira a credencial, o modelo, os parâmetros e as permissões. Nenhuma notícia foi enviada por esta execução.`);
}
if (tentativa >= LIMITE_TENTATIVAS) {
  // Limite atingido: falha rápida e clara em vez de esperar minutos indefinidamente.
  const codigo = status ? `HTTP ${status}` : 'falha de rede/timeout';
  throw new Error(`Gemini indisponível após ${tentativa} tentativa(s) imediatas (último erro: ${codigo}). A execução termina aqui sem enviar notícias. Na próxima execução programada o sistema tenta novamente.`);
}
// Reintentar de forma IMEDIATA: base ~10-16s. Respeita Retry-After/retryDelay do servidor, com teto de 60s.
const headers = resposta.headers || {};
const retryHeader = headers['retry-after'] || headers['Retry-After'];
let pedidoServidor = 0;
if (retryHeader) {
  const bruto = /^\d+(?:\.\d+)?$/.test(String(retryHeader))
    ? Number(retryHeader)
    : Math.max(0, (Date.parse(retryHeader) - Date.now()) / 1000);
  pedidoServidor = Math.min(bruto, 60); // teto de 60s para não travar a execução
}
for (const detalhe of body?.error?.details || []) {
  const segundos = /^([0-9]+(?:\.[0-9]+)?)s$/.exec(detalhe.retryDelay || '');
  if (segundos) pedidoServidor = Math.max(pedidoServidor, Math.min(Number(segundos[1]), 60));
}
const baseImediata = 10 + Math.floor(Math.random() * 7); // 10-16s
const esperaSegundos = Math.max(baseImediata, pedidoServidor);
return [{json: {
  geminiConcluido: false,
  tentativaGemini: tentativa,
  esperaSegundos,
  motivo: status ? `Gemini HTTP ${status}` : 'Timeout ou falha temporária de rede',
  proximaTentativa: new Date(Date.now() + esperaSegundos * 1000).toISOString(),
}}];
